                        </td>
                        <td class="statement-money" data-testid="statement-range-entry-credit">
                          @if (e.credit !== null) {
                            {{ e.credit | money: r.currency }}
                          }
                        </td>
                        <td class="statement-money" data-testid="statement-range-entry-balance">{{ e.balance | money: r.currency }}</td>
                      </tr>
